// === SITE SEARCH ======== >
// Self-hosted replacement for Google Programmable Search. The index
// (search.json) is generated by Jekyll at build time and fetched the first
// time the search box gets focus. Results render in a dropdown panel and
// the page URL is never changed.
(function () {
	var form = document.getElementById('site-search');
	if (!form) return;

	var input = document.getElementById('site-search-input');
	var panel = document.getElementById('site-search-results');
	var MAX_RESULTS = 8;
	var SNIPPET_RADIUS = 80;
	var pages = null;
	var loading = null;
	var activeIndex = -1;
	var debounceTimer;

	// Decode HTML entities left in the index (e.g. &amp;) into plain text.
	var decoder = document.createElement('textarea');
	function decode(str) {
		decoder.innerHTML = str;
		return decoder.value;
	}

	function escapeHtml(str) {
		return str.replace(/[&<>"']/g, function (c) {
			return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
		});
	}

	function escapeRegExp(str) {
		return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
	}

	function loadIndex() {
		if (!loading) {
			loading = fetch('/search.json')
				.then(function (res) { return res.json(); })
				.then(function (data) {
					pages = data.map(function (p) {
						var page = {
							title: decode(p.title),
							url: p.url,
							description: decode(p.description),
							text: decode(p.text)
						};
						page.titleLC = page.title.toLowerCase();
						page.descriptionLC = page.description.toLowerCase();
						page.textLC = page.text.toLowerCase();
						return page;
					});
				})
				.catch(function () { loading = null; });
		}
		return loading;
	}

	function countOccurrences(haystack, needle) {
		var count = 0, pos = haystack.indexOf(needle);
		while (pos !== -1) {
			count++;
			pos = haystack.indexOf(needle, pos + needle.length);
		}
		return count;
	}

	// Every term must appear somewhere in the page; title matches rank highest.
	function search(query) {
		var terms = query.toLowerCase().split(/\s+/).filter(function (t) { return t.length > 1; });
		if (!terms.length) return { terms: terms, results: [] };

		var results = [];
		pages.forEach(function (page) {
			var score = 0;
			for (var i = 0; i < terms.length; i++) {
				var t = terms[i];
				var inTitle = countOccurrences(page.titleLC, t);
				var inDescription = countOccurrences(page.descriptionLC, t);
				var inText = countOccurrences(page.textLC, t);
				if (!inTitle && !inDescription && !inText) return;
				score += inTitle * 10 + inDescription * 3 + inText;
			}
			results.push({ page: page, score: score });
		});
		results.sort(function (a, b) { return b.score - a.score; });
		return { terms: terms, results: results.slice(0, MAX_RESULTS) };
	}

	function highlight(str, terms) {
		var pattern = new RegExp('(' + terms.map(escapeRegExp).join('|') + ')', 'gi');
		return escapeHtml(str).replace(pattern, '<mark>$1</mark>');
	}

	// A short excerpt of the page text centred on the first matching term.
	function snippet(page, terms) {
		var pos = -1;
		for (var i = 0; i < terms.length && pos === -1; i++) {
			pos = page.textLC.indexOf(terms[i]);
		}
		if (pos === -1) return page.description;
		var start = Math.max(0, pos - SNIPPET_RADIUS);
		var end = Math.min(page.text.length, pos + SNIPPET_RADIUS);
		return (start > 0 ? '…' : '') + page.text.slice(start, end).trim() + (end < page.text.length ? '…' : '');
	}

	function render(query) {
		var found = search(query);
		activeIndex = -1;
		if (!found.terms.length) {
			close();
			return;
		}
		if (!found.results.length) {
			panel.innerHTML = '<p class="site-search-empty">No results for “' + escapeHtml(query) + '”</p>';
		} else {
			panel.innerHTML = found.results.map(function (r, i) {
				return '<a class="site-search-result" role="option" id="site-search-result-' + i + '" href="' + escapeHtml(r.page.url) + '">' +
					'<span class="site-search-title">' + highlight(r.page.title, found.terms) + '</span>' +
					'<span class="site-search-snippet">' + highlight(snippet(r.page, found.terms), found.terms) + '</span>' +
					'</a>';
			}).join('');
		}
		panel.hidden = false;
		input.setAttribute('aria-expanded', 'true');
	}

	function close() {
		panel.hidden = true;
		panel.innerHTML = '';
		activeIndex = -1;
		input.setAttribute('aria-expanded', 'false');
		input.removeAttribute('aria-activedescendant');
	}

	function setActive(index) {
		var items = panel.querySelectorAll('.site-search-result');
		if (!items.length) return;
		activeIndex = (index + items.length) % items.length;
		items.forEach(function (item, i) {
			item.classList.toggle('active', i === activeIndex);
		});
		items[activeIndex].scrollIntoView({ block: 'nearest' });
		input.setAttribute('aria-activedescendant', items[activeIndex].id);
	}

	function update() {
		var query = input.value.trim();
		loadIndex().then(function () {
			if (pages && input.value.trim() === query) render(query);
		});
	}

	input.addEventListener('focus', function () {
		loadIndex();
		if (input.value.trim()) update();
	});

	input.addEventListener('input', function () {
		clearTimeout(debounceTimer);
		debounceTimer = setTimeout(update, 120);
	});

	input.addEventListener('keydown', function (e) {
		if (e.key === 'ArrowDown') {
			e.preventDefault();
			setActive(activeIndex + 1);
		} else if (e.key === 'ArrowUp') {
			e.preventDefault();
			setActive(activeIndex - 1);
		} else if (e.key === 'Escape') {
			close();
			input.blur();
		}
	});

	// Enter (or the button) opens the highlighted result, or the top one.
	// The default form submission is cancelled so the URL stays clean.
	form.addEventListener('submit', function (e) {
		e.preventDefault();
		var items = panel.querySelectorAll('.site-search-result');
		if (!panel.hidden && items.length) {
			window.location.href = items[Math.max(activeIndex, 0)].getAttribute('href');
		} else {
			update();
		}
	});

	document.addEventListener('click', function (e) {
		if (!form.contains(e.target) && !panel.contains(e.target)) close();
	});
})();
